function y({registerIndicator:f,sourceValues:d,nulls:p}){f({id:"oa-sma",name:"Simple Moving Average (SMA)",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"sma",type:"line",title:"SMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(o,r){const a=Math.max(1,Math.floor(Number(r.period)||10)),n=d(o,r.source??"close"),i=new Array(o.length).fill(NaN),c=new Array(a).fill(NaN);let t=0,l=0,s=0;for(let e=0;e<o.length;e++){const u=c[t];Number.isFinite(u)?l-=u:s+=1;const m=Number.isFinite(n[e])?n[e]:0;l+=m,c[t]=m,t=(t+1)%a,i[e]=l/Math.max(1,s)}return{sma:p(i)}}})}export{y as default};
